//! End to end on a video ffmpeg generates: page changes between samples, so what
//! each sample sees is certain. Needs ffmpeg; skipped without it unless `CI` is set.

use slide_detect::{Error, Event, ExtractError, Slide, SlideParams, VideoInfo, detect};
use std::path::Path;
use std::process::Command;
use std::sync::atomic::{AtomicBool, Ordering};
use std::time::{Duration, Instant};

const FFMPEG: &str = "ffmpeg";

fn ffmpeg_available() -> bool {
    let available = Command::new(FFMPEG).arg("-version").output().is_ok();
    assert!(
        available || std::env::var_os("CI").is_none(),
        "CI must install ffmpeg"
    );
    available
}

/// A white 1280x720, 10 fps video with pages filled as `(color, from, to)`.
fn make_video(path: &Path, secs: u32, pages: &[(&str, f64, f64)]) {
    let filter = pages
        .iter()
        .map(|(color, from, to)| {
            format!("drawbox=color={color}:t=fill:enable='between(t,{from},{to})'")
        })
        .collect::<Vec<_>>()
        .join(",");
    let status = Command::new(FFMPEG)
        .args(["-hide_banner", "-loglevel", "error", "-y", "-f", "lavfi"])
        .args(["-i", &format!("color=c=white:s=1280x720:d={secs}:r=10")])
        .args(["-vf", &filter])
        .arg(path)
        .status()
        .unwrap();
    assert!(status.success());
}

fn params(cooldown: f64, stable_secs: f64) -> SlideParams {
    SlideParams {
        sample_interval: 0.5,
        similarity: 0.9,
        cooldown,
        stable_secs,
        roi: None,
    }
}

fn info(secs: u32) -> VideoInfo {
    VideoInfo {
        width: 1280,
        height: 720,
        duration: secs as f64,
    }
}

fn run(video: &Path, secs: u32, params: SlideParams, out: &Path) -> (Vec<Slide>, Vec<Event>) {
    let mut events = Vec::new();
    let slides = detect(
        Path::new(FFMPEG),
        video,
        info(secs),
        &params,
        out,
        &|| false,
        &mut |event| events.push(event),
    )
    .unwrap();
    (slides, events)
}

#[test]
fn slides_keep_their_true_times_through_a_cooldown() {
    if !ffmpeg_available() {
        return;
    }
    let dir = tempfile::tempdir().unwrap();
    let video = dir.path().join("synthetic.mp4");
    make_video(
        &video,
        20,
        &[
            ("black", 6.25, 7.25),
            ("gray", 7.25, 14.25),
            ("white", 14.25, 20.),
        ],
    );
    let out = dir.path().join("frames");
    let (slides, events) = run(&video, 20, params(10.0, 0.0), &out);
    let onsets: Vec<_> = slides.iter().map(|slide| slide.onset).collect();
    // White at 0. Black is replaced by gray at 7.5, which is emitted when the cooldown
    // ends with its first time. The last page is flushed at the end of the video.
    assert_eq!(onsets, [0.0, 7.5, 14.5]);
    for slide in &slides {
        let bytes = std::fs::read(out.join(&slide.file_name)).unwrap();
        assert_eq!(&bytes[..2], [0xff, 0xd8], "a JPEG");
    }
    assert_eq!(slides[1].file_name, "slide_0002.jpg");
    assert!(matches!(events[0], Event::ScanStarted { estimate: 40 }));
    assert!(events.contains(&Event::ExtractStarted { slides: 3 }));
    assert_eq!(
        events.last(),
        Some(&Event::Extracted { done: 3, slides: 3 })
    );
}

#[test]
fn stable_mode_waits_for_the_settled_picture() {
    if !ffmpeg_available() {
        return;
    }
    let dir = tempfile::tempdir().unwrap();
    let video = dir.path().join("synthetic.mp4");
    make_video(&video, 10, &[("black", 2.25, 3.75), ("gray", 3.75, 10.)]);
    let (slides, _) = run(&video, 10, params(2.0, 1.2), &dir.path().join("frames"));
    let onsets: Vec<_> = slides.iter().map(|slide| slide.onset).collect();
    // Black is sampled for 1.0 s, short of 1.2: only white and gray count.
    assert_eq!(onsets, [0.0, 4.0]);
}

#[test]
fn a_set_cancel_flag_stops_the_scan() {
    if !ffmpeg_available() {
        return;
    }
    let dir = tempfile::tempdir().unwrap();
    let video = dir.path().join("synthetic.mp4");
    make_video(&video, 2, &[("black", 0.75, 2.)]);
    let result = detect(
        Path::new(FFMPEG),
        &video,
        info(2),
        &params(0.0, 0.0),
        &dir.path().join("frames"),
        &|| true,
        &mut |_| {},
    );
    assert!(matches!(result, Err(Error::Cancelled)));
}

#[test]
fn an_unreadable_video_reports_ffmpegs_words() {
    if !ffmpeg_available() {
        return;
    }
    let dir = tempfile::tempdir().unwrap();
    let video = dir.path().join("broken.mp4");
    std::fs::write(&video, b"not a video").unwrap();
    let result = detect(
        Path::new(FFMPEG),
        &video,
        info(2),
        &params(0.0, 0.0),
        &dir.path().join("frames"),
        &|| false,
        &mut |_| {},
    );
    match result {
        Err(Error::ScanFailed { stderr, .. }) => assert!(!stderr.is_empty()),
        other => panic!("{other:?}"),
    }
}

#[test]
fn a_missing_ffmpeg_is_a_spawn_error() {
    let dir = tempfile::tempdir().unwrap();
    let result = detect(
        &dir.path().join("no-such-ffmpeg"),
        &dir.path().join("video.mp4"),
        info(2),
        &params(0.0, 0.0),
        &dir.path().join("frames"),
        &|| false,
        &mut |_| {},
    );
    assert!(matches!(result, Err(Error::Spawn(_))));
}

#[test]
fn a_failed_image_names_its_slide() {
    if !ffmpeg_available() {
        return;
    }
    let dir = tempfile::tempdir().unwrap();
    let video = dir.path().join("synthetic.mp4");
    make_video(&video, 2, &[("black", 0.75, 2.)]);
    let out = dir.path().join("frames");
    // A directory where the first image belongs.
    std::fs::create_dir_all(out.join("slide_0001.jpg")).unwrap();
    let result = detect(
        Path::new(FFMPEG),
        &video,
        info(2),
        &params(0.0, 0.0),
        &out,
        &|| false,
        &mut |_| {},
    );
    match result {
        Err(Error::Extract {
            number: 1,
            onset,
            source: ExtractError::Failed { .. },
        }) => assert_eq!(onset, 0.0),
        other => panic!("{other:?}"),
    }
}

#[test]
fn cancelling_midway_stops_either_pass_promptly() {
    if !ffmpeg_available() {
        return;
    }
    let dir = tempfile::tempdir().unwrap();
    let video = dir.path().join("synthetic.mp4");
    make_video(&video, 20, &[("black", 6.25, 20.)]);
    let stops: [fn(&Event) -> bool; 2] = [
        |event| matches!(event, Event::Sampled { frames: 3 }),
        |event| matches!(event, Event::ExtractStarted { .. }),
    ];
    for stop_at in stops {
        let flag = AtomicBool::new(false);
        let started = Instant::now();
        let result = detect(
            Path::new(FFMPEG),
            &video,
            info(20),
            &params(0.0, 0.0),
            &dir.path().join("frames"),
            &|| flag.load(Ordering::Relaxed),
            &mut |event| {
                if stop_at(&event) {
                    flag.store(true, Ordering::Relaxed);
                }
            },
        );
        assert!(matches!(result, Err(Error::Cancelled)), "{result:?}");
        assert!(started.elapsed() < Duration::from_secs(30));
    }
}

//! The decision: given sampled pictures in order, when does a slide begin?

use crate::{Roi, SlideParams};
use image::GrayImage;
use image_compare::Algorithm;
use std::borrow::Cow;

/// Three states: the last slide, the candidate under observation, and the time of
/// each. A cooldown only limits emitting, so detection has no blind spot.
pub(crate) struct Detector {
    params: SlideParams,
    last_emitted: Option<GrayImage>,
    candidate: Option<GrayImage>,
    candidate_first: Option<f64>,
    candidate_last: Option<f64>,
    last_emit: f64,
}

impl Detector {
    pub fn new(params: SlideParams) -> Self {
        Self {
            params,
            last_emitted: None,
            candidate: None,
            candidate_first: None,
            candidate_last: None,
            last_emit: f64::NEG_INFINITY,
        }
    }

    /// Takes the frame sampled at `t`; returns `(onset, capture)` when a slide is due.
    pub fn push(&mut self, t: f64, frame: &GrayImage) -> Option<(f64, f64)> {
        let compared = crop_roi(frame, self.params.roi);
        let similarity = self.params.similarity;
        let differs = |image: &GrayImage| {
            image.dimensions() != compared.dimensions() || ssim(image, &compared) < similarity
        };
        if !self.last_emitted.as_ref().is_none_or(differs) {
            // Back to the last slide: the candidate was a transition. Drop it.
            self.candidate = None;
            self.candidate_first = None;
            return None;
        }
        // A candidate that itself changed means an animation: restart its clock.
        if self.candidate.as_ref().is_none_or(differs) {
            self.candidate = Some(compared.into_owned());
            self.candidate_first = Some(t);
        }
        self.candidate_last = Some(t);
        let onset = self.candidate_first.unwrap_or(t);
        let capture = self.candidate_last.unwrap_or(t);
        if t - onset >= self.params.stable_secs && t - self.last_emit >= self.params.cooldown {
            self.last_emitted = self.candidate.take();
            self.candidate_first = None;
            self.candidate_last = None;
            self.last_emit = t;
            return Some((onset, capture));
        }
        None
    }

    /// At the end of the video a settled candidate is a slide even within a
    /// cooldown; otherwise the last slide would always be lost.
    pub fn finish(self) -> Option<(f64, f64)> {
        self.candidate.as_ref()?;
        let (onset, capture) = (self.candidate_first?, self.candidate_last?);
        (capture - onset >= self.params.stable_secs).then_some((onset, capture))
    }
}

/// Without a region the frame is borrowed, so most frames copy nothing.
fn crop_roi(image: &GrayImage, roi: Option<Roi>) -> Cow<'_, GrayImage> {
    let Some(roi) = roi else {
        return Cow::Borrowed(image);
    };
    let (w, h) = image.dimensions();
    let (x1, y1, x2, y2) = roi.pixels(w, h);
    Cow::Owned(
        image::imageops::crop_imm(image, x1, y1, (x2 - x1).max(1), (y2 - y1).max(1)).to_image(),
    )
}

impl Roi {
    /// The region in pixels of a `w`×`h` frame: `(x1, y1, x2, y2)`, never empty.
    pub fn pixels(&self, w: u32, h: u32) -> (u32, u32, u32, u32) {
        let sx = |v: f64| (v * w as f64).round() as u32;
        let sy = |v: f64| (v * h as f64).round() as u32;
        let (x1, x2) = (
            sx(self.x1).min(w.saturating_sub(1)),
            sx(self.x2).clamp(1, w),
        );
        let (y1, y2) = (
            sy(self.y1).min(h.saturating_sub(1)),
            sy(self.y2).clamp(1, h),
        );
        (x1, y1, x2.max(x1 + 1), y2.max(y1 + 1))
    }
}

fn ssim(a: &GrayImage, b: &GrayImage) -> f64 {
    image_compare::gray_similarity_structure(&Algorithm::MSSIMSimple, a, b)
        .map(|s| s.score)
        .unwrap_or(0.0)
}

#[cfg(test)]
mod tests {
    use super::*;

    /// A frame with distinct structure per `seed`, as SSIM needs to tell them apart.
    fn frame(seed: u8) -> GrayImage {
        GrayImage::from_fn(64, 64, |x, y| {
            let band = ((x / 8) as u8).wrapping_mul(seed) ^ ((y / 8) as u8).wrapping_mul(seed / 2);
            image::Luma([band.wrapping_mul(37)])
        })
    }

    fn params(cooldown: f64, stable_secs: f64) -> SlideParams {
        SlideParams {
            sample_interval: 0.5,
            similarity: 0.9,
            cooldown,
            stable_secs,
            roi: None,
        }
    }

    /// Runs samples 0.5 s apart; returns every `(onset, capture)` and the flush.
    fn run(params: SlideParams, seeds: &[u8]) -> Vec<(f64, f64)> {
        let mut detector = Detector::new(params);
        let mut out: Vec<_> = seeds
            .iter()
            .enumerate()
            .filter_map(|(i, seed)| detector.push(i as f64 * 0.5, &frame(*seed)))
            .collect();
        out.extend(detector.finish());
        out
    }

    #[test]
    fn a_change_is_a_slide_and_a_repeat_is_not() {
        let found = run(params(0.0, 0.0), &[1, 1, 1, 9, 9, 9]);
        assert_eq!(found, [(0.0, 0.0), (1.5, 1.5)]);
    }

    #[test]
    fn a_slide_during_a_cooldown_keeps_its_true_time() {
        // Page 9 appears at 1.0 s; the cooldown ends at 2.0 s.
        let found = run(params(2.0, 0.0), &[1, 1, 9, 9, 9, 9, 9]);
        assert_eq!(found, [(0.0, 0.0), (1.0, 2.0)]);
    }

    #[test]
    fn the_last_page_survives_a_cooldown() {
        let found = run(params(100.0, 0.0), &[1, 1, 9, 9]);
        assert_eq!(found, [(0.0, 0.0), (1.0, 1.5)]);
    }

    #[test]
    fn stable_mode_skips_a_passing_transition() {
        // 5 shows for 0.5 s, then 9 settles.
        let found = run(params(0.0, 1.0), &[1, 1, 1, 5, 5, 9, 9, 9, 9]);
        assert_eq!(found, [(0.0, 1.0), (2.5, 3.5)]);
    }

    #[test]
    fn returning_to_the_last_slide_drops_the_candidate() {
        let found = run(params(100.0, 0.0), &[1, 1, 9, 1, 1]);
        assert_eq!(found, [(0.0, 0.0)]);
    }

    #[test]
    fn changes_outside_the_region_are_ignored() {
        let roi = Some(Roi {
            x1: 0.0,
            y1: 0.0,
            x2: 0.5,
            y2: 1.0,
        });
        let mut detector = Detector::new(SlideParams {
            roi,
            ..params(0.0, 0.0)
        });
        let base = frame(1);
        let mut changed = base.clone();
        for (x, _, pixel) in changed.enumerate_pixels_mut() {
            if x >= 40 {
                *pixel = image::Luma([255]);
            }
        }
        assert!(detector.push(0.0, &base).is_some());
        assert!(detector.push(0.5, &changed).is_none());
    }

    #[test]
    fn regions_are_never_empty() {
        let roi = Roi {
            x1: 1.0,
            y1: 1.0,
            x2: 1.0,
            y2: 1.0,
        };
        assert_eq!(roi.pixels(10, 10), (9, 9, 10, 10));
    }
}

//! Finds the slide changes in a video, and extracts a full-resolution JPEG of each.
//!
//! ffmpeg decodes a small grayscale stream, one frame every
//! [`SlideParams::sample_interval`] seconds. A frame that differs from the last
//! slide by SSIM becomes a candidate; it becomes a slide once it has held for
//! [`SlideParams::stable_secs`] and [`SlideParams::cooldown`] has passed since the
//! last slide. Detection never sleeps during a cooldown, so a slide's time is when
//! it first appeared, not when the cooldown ended.
//!
//! The caller supplies the ffmpeg path and the video's dimensions and duration, and
//! receives typed [`Event`]s and [`Error`]s: the crate has no user-facing text.

mod detector;
mod extract;
mod scan;

use std::fmt;
use std::path::{Path, PathBuf};

/// Detection settings.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct SlideParams {
    /// Seconds between sampled frames.
    pub sample_interval: f64,
    /// SSIM below this (0 to 1) counts as a different picture.
    pub similarity: f64,
    /// Minimum seconds between two slides.
    pub cooldown: f64,
    /// How long a picture must hold to count; 0 accepts it at once. Above 0, a
    /// transition that never settles produces no slide.
    pub stable_secs: f64,
    /// Compare only this region; everything else may change freely.
    pub roi: Option<Roi>,
}

/// A region of the frame, as fractions of its width and height (0 to 1).
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Roi {
    pub x1: f64,
    pub y1: f64,
    pub x2: f64,
    pub y2: f64,
}

/// The video to scan, as the caller's probe reported it.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct VideoInfo {
    pub width: u32,
    pub height: u32,
    /// Seconds; only used to estimate progress.
    pub duration: f64,
}

/// One detected slide. The image is `file_name` in the output directory.
#[derive(Debug, Clone, PartialEq)]
pub struct Slide {
    /// When the picture first appeared: the time to align a transcript with.
    pub onset: f64,
    /// When the image was taken: the last sample of the settled picture.
    pub capture: f64,
    /// `slide_0001.jpg`, numbered from 1 in time order.
    pub file_name: String,
}

/// What [`detect`] is doing, in order: one `ScanStarted`, any number of `Sampled`
/// and `CandidateFound`, one `ScanFinished`; then, if anything was found, one
/// `ExtractStarted` and one `Extracted` per slide.
#[derive(Debug, Clone, Copy, PartialEq)]
pub enum Event {
    /// `estimate` is the frame count the duration suggests, not a promise: variable
    /// frame rate input may land a frame or two away.
    ScanStarted {
        estimate: u64,
    },
    Sampled {
        frames: u64,
    },
    CandidateFound {
        slides: usize,
    },
    ScanFinished {
        frames: u64,
        slides: usize,
    },
    ExtractStarted {
        slides: usize,
    },
    Extracted {
        done: usize,
        slides: usize,
    },
}

/// Why [`detect`] stopped.
#[derive(Debug)]
pub enum Error {
    /// `cancelled` returned true.
    Cancelled,
    /// ffmpeg could not start for the scan.
    Spawn(std::io::Error),
    /// The scan's ffmpeg failed; `stderr` holds the end of its output.
    ScanFailed {
        status: std::process::ExitStatus,
        stderr: String,
    },
    /// The scan ended with no slide, as for a video with no frames.
    NoFrames,
    /// The image of slide `number` (from 1), which first appeared at `onset`, failed.
    Extract {
        number: usize,
        onset: f64,
        source: ExtractError,
    },
    Io(std::io::Error),
}

/// Why one image could not be extracted.
#[derive(Debug)]
pub enum ExtractError {
    Spawn(std::io::Error),
    /// ffmpeg failed; `stderr` holds the end of its output.
    Failed {
        code: Option<i32>,
        stderr: String,
    },
    /// ffmpeg reported success and the file is not there.
    Missing(PathBuf),
}

impl fmt::Display for Error {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Cancelled => f.write_str("cancelled"),
            Self::Spawn(_) => f.write_str("could not start ffmpeg"),
            Self::ScanFailed { status, stderr } => {
                write!(f, "ffmpeg failed ({status}): {stderr}")
            }
            Self::NoFrames => f.write_str("no frames sampled"),
            Self::Extract { number, onset, .. } => {
                write!(f, "could not extract slide {number} (t={onset:.1}s)")
            }
            Self::Io(_) => f.write_str("frame stream or output directory failed"),
        }
    }
}

impl std::error::Error for Error {
    fn source(&self) -> Option<&(dyn std::error::Error + 'static)> {
        match self {
            Self::Spawn(error) | Self::Io(error) => Some(error),
            Self::Extract { source, .. } => Some(source),
            Self::Cancelled | Self::ScanFailed { .. } | Self::NoFrames => None,
        }
    }
}

impl fmt::Display for ExtractError {
    fn fmt(&self, f: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::Spawn(error) => write!(f, "could not start ffmpeg: {error}"),
            Self::Failed { code, stderr } => write!(f, "ffmpeg failed ({code:?}): {stderr}"),
            Self::Missing(path) => write!(f, "ffmpeg did not produce {}", path.display()),
        }
    }
}

impl std::error::Error for ExtractError {}

/// Detects the slides of `video` and writes their images to `output_dir`, created if
/// needed. Blocking. `cancelled` is polled about ten times a second; once it returns
/// true every ffmpeg is killed and [`Error::Cancelled`] returned. `on_event` runs on
/// the calling thread.
pub fn detect(
    ffmpeg: &Path,
    video: &Path,
    info: VideoInfo,
    params: &SlideParams,
    output_dir: &Path,
    cancelled: &(dyn Fn() -> bool + Sync),
    on_event: &mut dyn FnMut(Event),
) -> Result<Vec<Slide>, Error> {
    std::fs::create_dir_all(output_dir).map_err(Error::Io)?;
    let times = scan::scan(ffmpeg, video, info, params, cancelled, on_event)?;
    if times.is_empty() {
        return Err(Error::NoFrames);
    }
    extract::extract(ffmpeg, video, &times, output_dir, cancelled, on_event)
}

/// How often a blocked wait looks at `cancelled`.
const POLL: std::time::Duration = std::time::Duration::from_millis(100);

//! The second pass: one full-resolution JPEG per slide.

use crate::scan::tail_lines;
use crate::{Error, Event, ExtractError, POLL, Slide};
use std::io::Read;
use std::path::Path;
use std::process::{Command, Stdio};
use std::sync::atomic::{AtomicBool, AtomicUsize, Ordering};
use std::sync::mpsc::{RecvTimeoutError, channel};
use std::time::Duration;

/// One ffmpeg per image: four use the cores without a storm of processes.
const CONCURRENCY: usize = 4;

const CHILD_POLL: Duration = Duration::from_millis(20);

fn file_name(number: usize) -> String {
    format!("slide_{number:04}.jpg")
}

pub(crate) fn extract(
    ffmpeg: &Path,
    video: &Path,
    times: &[(f64, f64)],
    output_dir: &Path,
    cancelled: &(dyn Fn() -> bool + Sync),
    on_event: &mut dyn FnMut(Event),
) -> Result<Vec<Slide>, Error> {
    let slides = times.len();
    on_event(Event::ExtractStarted { slides });
    let next = AtomicUsize::new(0);
    // Set on the way out, whatever the reason, so running children are killed.
    let stop = AtomicBool::new(false);
    let (sender, results) = channel::<(usize, Result<(), ExtractError>)>();
    std::thread::scope(|scope| {
        for _ in 0..CONCURRENCY.min(slides) {
            let sender = sender.clone();
            let (next, stop) = (&next, &stop);
            scope.spawn(move || {
                while !stop.load(Ordering::Relaxed) {
                    let index = next.fetch_add(1, Ordering::Relaxed);
                    let Some((_, capture)) = times.get(index) else {
                        return;
                    };
                    let dest = output_dir.join(file_name(index + 1));
                    let result = extract_frame(ffmpeg, video, *capture, &dest, stop);
                    if sender.send((index, result)).is_err() {
                        return;
                    }
                }
            });
        }
        drop(sender);
        let outcome = wait(&results, times, cancelled, on_event);
        stop.store(true, Ordering::Relaxed);
        outcome
    })?;
    Ok(times
        .iter()
        .enumerate()
        .map(|(index, (onset, capture))| Slide {
            onset: *onset,
            capture: *capture,
            file_name: file_name(index + 1),
        })
        .collect())
}

fn wait(
    results: &std::sync::mpsc::Receiver<(usize, Result<(), ExtractError>)>,
    times: &[(f64, f64)],
    cancelled: &(dyn Fn() -> bool + Sync),
    on_event: &mut dyn FnMut(Event),
) -> Result<(), Error> {
    let mut done = 0;
    while done < times.len() {
        if cancelled() {
            return Err(Error::Cancelled);
        }
        match results.recv_timeout(POLL) {
            Ok((_, Ok(()))) => {
                done += 1;
                on_event(Event::Extracted {
                    done,
                    slides: times.len(),
                });
            }
            Ok((index, Err(source))) => {
                return Err(Error::Extract {
                    number: index + 1,
                    onset: times[index].0,
                    source,
                });
            }
            Err(RecvTimeoutError::Timeout) => {}
            Err(RecvTimeoutError::Disconnected) => break,
        }
    }
    Ok(())
}

/// One exact frame. A stopped extraction reports no error of its own: the caller is
/// already leaving, for a reason it knows.
fn extract_frame(
    ffmpeg: &Path,
    video: &Path,
    t: f64,
    dest: &Path,
    stop: &AtomicBool,
) -> Result<(), ExtractError> {
    let seek = format!("{t:.3}");
    // -q:v 2 is JPEG's high-quality end (2 to 31, lower is better): slides are text.
    let mut child = Command::new(ffmpeg)
        .args(["-hide_banner", "-loglevel", "error", "-y", "-ss", &seek])
        .arg("-i")
        .arg(video)
        .args(["-frames:v", "1", "-q:v", "2"])
        .arg(dest)
        .stdin(Stdio::null())
        .stdout(Stdio::null())
        .stderr(Stdio::piped())
        .spawn()
        .map_err(ExtractError::Spawn)?;
    let stderr = child.stderr.take();
    let stderr = std::thread::spawn(move || {
        let mut text = Vec::new();
        if let Some(mut stderr) = stderr {
            let _ = stderr.read_to_end(&mut text);
        }
        String::from_utf8_lossy(&text).into_owned()
    });
    let status = loop {
        if stop.load(Ordering::Relaxed) {
            let _ = child.kill();
            let _ = child.wait();
            return Ok(());
        }
        match child.try_wait() {
            Ok(Some(status)) => break status,
            Ok(None) => std::thread::sleep(CHILD_POLL),
            Err(error) => {
                let _ = child.kill();
                let _ = child.wait();
                return Err(ExtractError::Spawn(error));
            }
        }
    };
    if !status.success() {
        return Err(ExtractError::Failed {
            code: status.code(),
            stderr: tail_lines(&stderr.join().unwrap_or_default()),
        });
    }
    if dest.is_file() {
        Ok(())
    } else {
        Err(ExtractError::Missing(dest.to_owned()))
    }
}

